  "x_axis": {
    "mode": "C16",
    "name": "疯狂 (Madness)",
    "definition": "疯者处于非正常状态，伤害受害者或被清醒者审视",
    "manifestation": "男主利用超忆症构建虚假记忆，女主在失忆中被迫依赖，两人建立基于病态逻辑的排他性关系。"
  },
  "y_axis": {
    "tags": ["规则怪谈", "双向暗恋"],
    "effects": "规则怪谈提供压抑封闭的环境（精神病院）和必须遵守的仪式（吃药、作息），双向暗恋在规则缝隙中滋生，形成极致的禁忌感与依赖感。"
  },
  "reaction": {
    "strength": "↘",
    "description": "中度反应（冲突加剧）。标签为模式增加道德困境与悲剧必然性。正常的恋爱被异化为实验与控制，但这种控制反而是两人唯一的救赎。"
  },
  "tension_level": 4,
  "platform": "知乎盐选/晋江",
  "forbidden_elements": ["不要出现真正的超自然鬼怪（保持心理惊悚）", "不要BE（虽然病态但要在一起）", "不要虐女主太狠（侧重心理控制而非肉体折磨）"],
  "target_length": "6500-10000字"
}", "path": "creative_intent.json"}

{"files": [{"content": "{
  "protagonists": [
    {
      "name": "陆沉 (编号001)",
      "role": "男主",
      "traits": [
        "超忆症 (Hyperthymesia)",
        "狂躁症 (平时极度克制，失控时毁灭性)",
        "表演型人格 (每天都在演完美的初恋)",
        "病娇 (极致的占有与控制)"
      ],
      "goals": {
        "explicit": "每天让林浅重新爱上自己，完成当天的'治疗指标'。",
        "implicit": "将林浅永远困在只有两个人的世界里，因为外界不配拥有她。",
        "fear": "林浅康复，记起一切后抛弃他这个'怪物'。"
      }
    },
    {
      "name": "林浅 (编号007)",
      "role": "女主",
      "traits": [
        "顺行性遗忘 (记忆每天重置)",
        "重度抑郁 (伴随自毁倾向)",
        "直觉敏锐 (身体记忆强于大脑)",
        "斯德哥尔摩潜质 (渴望被绝对掌控)"
      ],
      "goals": {
        "explicit": "在这个陌生的白色恐怖世界里寻找安全感。",
        "implicit": "寻找一个能完全接纳她破碎灵魂的容器。",
        "fear": "被世界遗忘，独自面对虚无。"
      }
    }
  ],
  "supporting_characters": [
    {
      "name": "陈医生",
      "role": "观察者/反派",
      "traits": ["冷酷理性", "数据至上"],
      "function": "代表'正常世界'的规则，将两人的爱情视为'实验数据'，不断施加压力测试他们的极限。"
    }
  ],
  "relationships": [
    {
      "source": "陆沉",
      "target": "林浅",
      "description": "饲主与金丝雀，也是唯一的锚点。利用她的失忆构建完美剧本。"
    },
    {
      "source": "林浅",
      "target": "陆沉",
      "description": "唯一的救命稻草，从依赖到觉醒后的共生。"
    }
  ]
}", "path": "characters.json"}, {"content": "{
  "act_one": {
    "title": "第N+1次初恋",
    "word_count": "1500-2000",
    "key_events": [
      "林浅在白色病房醒来，面对《病人行为守则》（规则怪谈元素：不要直视镜子、按时吃药）。",
      "陆沉登场，利用超忆症精准说出林浅此刻的感受，伪装成'一见钟情'的病友。",
      "两人在放风时间的互动，陆沉展示了惊人的细节掌控力（记得风吹过树叶的角度）。",
      "林浅在药瓶底部发现一行微小的刻字：'别信医生'。"
    ],
    "tension_point": "林浅对陌生环境的恐惧 vs 陆沉带来的奇异安全感。"
  },
  "act_two": {
    "title": "墙壁里的秘密",
    "word_count": "3000-5000",
    "key_events": [
      "陈医生介入，进行'暴露疗法'，试图强行唤醒林浅记忆，导致林浅痛苦崩溃。",
      "陆沉狂躁症发作，为了保护林浅差点伤人，被关禁闭。",
      "林浅独自探索，在隐蔽的墙角发现密密麻麻的刻字：'今天她笑了3次'、'今天她哭了1次'，记录跨度长达三年。",
      "中点转折：林浅并没有完全失忆，她记起了昨天的片段，意识到陆沉在演戏。",
      "林浅开始试探陆沉，发现他故意隐瞒了她可以康复的事实。"
    ],
    "tension_point": "真相的恐怖 vs 情感的依赖。他是爱人还是狱卒？"
  },
  "act_three": {
    "title": "自愿的疯子",
    "word_count": "2000-3000",
    "key_events": [
      "林浅当面拆穿陆沉，陆沉卸下伪装，展现出偏执疯狂的一面：'只有疯子的爱情才纯粹'。",
      "陈医生宣布实验结束，准备将两人分开（因为产生了不可控的情感）。",
      "高潮：林浅面临选择——康复出院回到冷漠的正常世界，还是装疯留下。",
      "结局：林浅对医生撒谎说自己什么都不记得了，转身对陆沉说：'那你明天记得再追我一次'。",
      "尾声：两人在病历本上共同写下新的'观察记录'，成为了共犯。"
    ],
    "tension_point": "正常世界的自由 vs 疯人院里的爱情。"
  }
}", "path": "outline.json"}]}

